 "content": "def transform(grid):
    out = [row[:] for row in grid]
    fives = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    # The source anchor is part of the multicolored pattern; the isolated 5 marks its destination.
    def has_neighbor(r, c):
        return any(0 <= r + dr < len(grid) and 0 <= c + dc < len(grid[0])
                   and grid[r + dr][c + dc] != 0
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc)
    source = next((p for p in fives if has_neighbor(*p)), None)
    target = next((p for p in fives if p != source and not has_neighbor(*p)), None)
    if source is None or target is None:
        return out
    dr, dc = target[0] - source[0], target[1] - source[1]
    out[target[0]][target[1]] = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and (r, c) != source:
                rr, cc = r + dr, c + dc
                if 0 <= rr < len(out) and 0 <= cc < len(out[0]):
                    out[rr][cc] = value
    return out
